// ============================================================================
// Unidad 4 (Gobernanza de IT) — Bonus: una IA como asesora de ajedrez
//
// Convención: comentarios en español, identificadores en inglés.
//
// Idea central: el modelo de IA es un ADAPTADOR. Sugiere una jugada; el núcleo
// decide si es válida. La IA asesora, no arbitra.
//
//   Núcleo (no sabe nada de HTTP, claves ni proveedores):
//       UciMove, IChessAdvisor, AdvisedMoveSelector, IAdvisorLog
//   Adaptadores (detalles intercambiables):
//       LlmChessAdvisor (API de IA por HTTP), RandomChessAdvisor (respaldo)
//
// Requisitos: .NET 6 o superior (usa record struct y System.Text.Json).
// Para probarlo como programa suelto, compilar con la constante BONUS_DEMO
// (<DefineConstants>BONUS_DEMO</DefineConstants> en el .csproj). Sin esa
// constante, el archivo se integra al TPO sin traer un Main propio.
//
// Cada decisión de gobernanza de la clase está marcada con [GOBERNANZA].
//
// Nota: este ejemplo fue escrito pensando en la API de Mensajes de Anthropic.
// Antes de usarlo, revisar en la documentación oficial (docs.claude.com) la
// URL, las cabeceras y el nombre del modelo vigentes.
// ============================================================================

#nullable enable

using System;
using System.Collections.Generic;
using System.Linq;
using System.Net.Http;
using System.Text;
using System.Text.Json;
using System.Text.RegularExpressions;
using System.Threading;
using System.Threading.Tasks;

namespace ChessExamples.AiAdvisor
{
    // ========================================================================
    // NÚCLEO
    // ========================================================================

    // Una jugada en notación UCI: casilla origen + casilla destino (+ promoción).
    // Ejemplos: "e2e4", "g1f3", "e7e8q".
    public readonly record struct UciMove(string Text)
    {
        private static readonly Regex Pattern =
            new(@"^[a-h][1-8][a-h][1-8][qrbn]?$", RegexOptions.Compiled);

        public static bool TryParse(string? text, out UciMove move)
        {
            move = default;
            if (text is null) return false;
            var normalized = text.Trim().ToLowerInvariant();
            if (!Pattern.IsMatch(normalized)) return false;
            move = new UciMove(normalized);
            return true;
        }

        public override string ToString() => Text;
    }

    // El contrato que el núcleo necesita. No dice cómo se decide la jugada:
    // puede ser una API de IA, un algoritmo minimax o un azar.
    public interface IChessAdvisor
    {
        string Name { get; }

        // Recibe la posición (FEN) y las jugadas legales. Devuelve una sugerencia
        // o null si no tiene ninguna. Puede lanzar excepciones: el núcleo las contiene.
        Task<UciMove?> SuggestMoveAsync(
            string fen, IReadOnlyList<UciMove> legalMoves, CancellationToken ct);
    }

    // [GOBERNANZA] Registro de decisiones: qué se sugirió, qué se jugó y por qué.
    // Sirve para auditar (tema de la próxima clase).
    public record AdvisorDecision(
        string Fen, string AdvisorName, string? Suggested, string Final, string Outcome);

    public interface IAdvisorLog
    {
        void Record(AdvisorDecision decision);
    }

    public sealed class ConsoleAdvisorLog : IAdvisorLog
    {
        public void Record(AdvisorDecision d) =>
            Console.WriteLine(
                $"[advisor] {d.AdvisorName} sugirió={d.Suggested ?? "-"} " +
                $"jugada={d.Final} resultado={d.Outcome}");
    }

    // El corazón del ejemplo. Acá viven las reglas que el núcleo NO delega:
    //  - la jugada final siempre es una jugada legal;
    //  - si el asesor falla, se demora o devuelve algo inválido, el juego sigue.
    public sealed class AdvisedMoveSelector
    {
        private readonly IChessAdvisor primary;
        private readonly IChessAdvisor fallback;
        private readonly IAdvisorLog log;
        private readonly TimeSpan timeout;

        public AdvisedMoveSelector(
            IChessAdvisor primary, IChessAdvisor fallback, IAdvisorLog log, TimeSpan timeout)
        {
            this.primary = primary;
            this.fallback = fallback;
            this.log = log;
            this.timeout = timeout;   // [GOBERNANZA] límite de tiempo: control de recursos y disponibilidad
        }

        public async Task<UciMove> ChooseAsync(
            string fen, IReadOnlyList<UciMove> legalMoves, CancellationToken ct = default)
        {
            if (legalMoves.Count == 0)
                throw new ArgumentException("No hay jugadas legales.", nameof(legalMoves));

            string outcome;
            UciMove? suggested = null;

            try
            {
                using var cts = CancellationTokenSource.CreateLinkedTokenSource(ct);
                cts.CancelAfter(timeout);

                suggested = await primary.SuggestMoveAsync(fen, legalMoves, cts.Token);

                if (suggested is null)
                {
                    outcome = "sin-sugerencia";
                }
                // [GOBERNANZA] La salida del modelo es una entrada NO confiable:
                // se valida contra las jugadas legales antes de usarla.
                else if (!legalMoves.Contains(suggested.Value))
                {
                    outcome = "jugada-ilegal";
                }
                else
                {
                    log.Record(new AdvisorDecision(
                        fen, primary.Name, suggested.Value.Text, suggested.Value.Text, "aceptada"));
                    return suggested.Value;
                }
            }
            catch (OperationCanceledException) when (!ct.IsCancellationRequested)
            {
                outcome = "timeout";
            }
            catch (HttpRequestException)
            {
                outcome = "error-de-red";
            }

            // [GOBERNANZA] Respaldo local: si la IA no está, el juego continúa
            // (continuidad del servicio, Unidad 6).
            var backup = await fallback.SuggestMoveAsync(fen, legalMoves, ct);
            var final = backup is { } b && legalMoves.Contains(b) ? b : legalMoves[0];

            log.Record(new AdvisorDecision(
                fen, primary.Name, suggested?.Text, final.Text, "respaldo:" + outcome));
            return final;
        }
    }

    // ========================================================================
    // ADAPTADORES
    // ========================================================================

    // Respaldo y doble de prueba: elige una jugada legal al azar.
    public sealed class RandomChessAdvisor : IChessAdvisor
    {
        private readonly Random random;

        public RandomChessAdvisor(int? seed = null) =>
            random = seed is null ? new Random() : new Random(seed.Value);

        public string Name => "random";

        public Task<UciMove?> SuggestMoveAsync(
            string fen, IReadOnlyList<UciMove> legalMoves, CancellationToken ct)
        {
            UciMove? move = legalMoves.Count == 0 ? null : legalMoves[random.Next(legalMoves.Count)];
            return Task.FromResult(move);
        }
    }

    public record LlmAdvisorOptions(
        string ApiKey,
        string Model = "claude-sonnet-5-5",
        string Endpoint = "https://api.anthropic.com/v1/messages",
        int MaxTokens = 20);   // [GOBERNANZA] tope de tokens: controla el costo

    // Adaptador que habla con una API de IA por HTTP.
    // Se puede reemplazar por otro proveedor sin tocar el núcleo.
    public sealed class LlmChessAdvisor : IChessAdvisor
    {
        private const string SystemPrompt =
            "Sos un asesor de ajedrez. Respondés únicamente con una jugada en notación " +
            "UCI (por ejemplo e2e4), elegida de la lista de jugadas legales provista. " +
            "No agregues explicaciones.";

        private readonly HttpClient http;
        private readonly LlmAdvisorOptions options;

        public LlmChessAdvisor(HttpClient http, LlmAdvisorOptions options)
        {
            this.http = http;
            this.options = options;
        }

        public string Name => "llm:" + options.Model;

        public async Task<UciMove?> SuggestMoveAsync(
            string fen, IReadOnlyList<UciMove> legalMoves, CancellationToken ct)
        {
            // [GOBERNANZA] Minimización de datos: se envía SOLO la posición y las
            // jugadas legales. Nada de nombres, cuentas ni datos personales
            // (principio de finalidad y seguridad de la Ley 25.326).
            var body = new
            {
                model = options.Model,
                max_tokens = options.MaxTokens,
                system = SystemPrompt,
                messages = new[]
                {
                    new { role = "user", content = BuildPrompt(fen, legalMoves) }
                }
            };

            using var request = new HttpRequestMessage(HttpMethod.Post, options.Endpoint)
            {
                Content = new StringContent(
                    JsonSerializer.Serialize(body), Encoding.UTF8, "application/json")
            };
            request.Headers.Add("x-api-key", options.ApiKey);
            request.Headers.Add("anthropic-version", "2023-06-01");

            using var response = await http.SendAsync(request, ct);
            response.EnsureSuccessStatusCode();

            var json = await response.Content.ReadAsStringAsync(ct);
            return ExtractMove(json);
        }

        // Si algún día se mezclara texto escrito por una persona en el prompt,
        // habría que tratarlo como no confiable (inyección de instrucciones).
        // Acá la entrada la genera el propio juego, por eso el riesgo es bajo.
        public static string BuildPrompt(string fen, IReadOnlyList<UciMove> legalMoves) =>
            $"Posición (FEN): {fen}\n" +
            $"Jugadas legales (UCI): {string.Join(' ', legalMoves)}\n" +
            "Elegí la mejor jugada de la lista. Respondé únicamente con la jugada.";

        // Público y estático para poder probarlo sin red.
        // Busca la primera jugada con formato UCI dentro del texto de la respuesta.
        public static UciMove? ExtractMove(string json)
        {
            try
            {
                using var doc = JsonDocument.Parse(json);
                if (!doc.RootElement.TryGetProperty("content", out var content) ||
                    content.ValueKind != JsonValueKind.Array)
                    return null;

                foreach (var block in content.EnumerateArray())
                {
                    if (!block.TryGetProperty("type", out var type) || type.GetString() != "text")
                        continue;
                    var text = block.TryGetProperty("text", out var t) ? t.GetString() : null;
                    if (text is null) continue;

                    var match = Regex.Match(text.ToLowerInvariant(), @"\b[a-h][1-8][a-h][1-8][qrbn]?\b");
                    if (match.Success && UciMove.TryParse(match.Value, out var move))
                        return move;
                }
                return null;
            }
            catch (JsonException)
            {
                return null;
            }
        }
    }

    public static class AdvisorFactory
    {
        // [GOBERNANZA] La clave de API vive en una variable de entorno, NUNCA en
        // el repositorio. Si no está configurada, el juego usa el respaldo local.
        public static IChessAdvisor CreateFromEnvironment(HttpClient http, IChessAdvisor fallback)
        {
            var apiKey = Environment.GetEnvironmentVariable("ANTHROPIC_API_KEY");
            if (string.IsNullOrWhiteSpace(apiKey))
            {
                Console.WriteLine("[advisor] ANTHROPIC_API_KEY no está definida: se usa el respaldo local.");
                return fallback;
            }

            var model = Environment.GetEnvironmentVariable("CHESS_AI_MODEL");
            var options = string.IsNullOrWhiteSpace(model)
                ? new LlmAdvisorOptions(apiKey)
                : new LlmAdvisorOptions(apiKey, model);
            return new LlmChessAdvisor(http, options);
        }
    }

    // ========================================================================
    // PRUEBAS (sin framework: alcanza con llamar a AdvisorChecks.RunAllAsync())
    // Dobles de prueba: el núcleo se prueba sin red y sin clave de API.
    // ========================================================================

    internal sealed class FixedAdvisor : IChessAdvisor
    {
        private readonly UciMove? move;
        public FixedAdvisor(UciMove? move) => this.move = move;
        public string Name => "fixed";
        public Task<UciMove?> SuggestMoveAsync(string fen, IReadOnlyList<UciMove> m, CancellationToken ct) =>
            Task.FromResult(move);
    }

    internal sealed class ThrowingAdvisor : IChessAdvisor
    {
        public string Name => "throwing";
        public Task<UciMove?> SuggestMoveAsync(string fen, IReadOnlyList<UciMove> m, CancellationToken ct) =>
            throw new HttpRequestException("API caída (simulada)");
    }

    internal sealed class SlowAdvisor : IChessAdvisor
    {
        public string Name => "slow";
        public async Task<UciMove?> SuggestMoveAsync(string fen, IReadOnlyList<UciMove> m, CancellationToken ct)
        {
            await Task.Delay(Timeout.Infinite, ct);   // se queda esperando hasta que lo cancelen
            return null;
        }
    }

    internal sealed class MemoryLog : IAdvisorLog
    {
        public List<AdvisorDecision> Decisions { get; } = new();
        public void Record(AdvisorDecision d) => Decisions.Add(d);
    }

    public static class AdvisorChecks
    {
        private const string StartFen = "rnbqkbnr/pppppppp/8/8/8/8/PPPPPPPP/RNBQKBNR w KQkq - 0 1";

        private static readonly IReadOnlyList<UciMove> Legal = new[]
        {
            new UciMove("e2e4"), new UciMove("d2d4"), new UciMove("g1f3"), new UciMove("b1c3")
        };

        private static void Check(bool condition, string name)
        {
            Console.WriteLine((condition ? "OK     " : "FALLÓ  ") + name);
            if (!condition) throw new InvalidOperationException("Falló: " + name);
        }

        private static AdvisedMoveSelector Selector(IChessAdvisor primary, MemoryLog log) =>
            new(primary, new RandomChessAdvisor(seed: 1), log, TimeSpan.FromMilliseconds(100));

        public static async Task RunAllAsync()
        {
            // 1. Una sugerencia legal se acepta tal cual.
            var log = new MemoryLog();
            var move = await Selector(new FixedAdvisor(new UciMove("g1f3")), log).ChooseAsync(StartFen, Legal);
            Check(move.Text == "g1f3" && log.Decisions[0].Outcome == "aceptada", "sugerencia legal aceptada");

            // 2. Una sugerencia ILEGAL jamás llega al tablero: se usa el respaldo.
            log = new MemoryLog();
            move = await Selector(new FixedAdvisor(new UciMove("e2e5")), log).ChooseAsync(StartFen, Legal);
            Check(Legal.Contains(move) && log.Decisions[0].Outcome == "respaldo:jugada-ilegal",
                  "jugada ilegal descartada");

            // 3. Si el asesor no tiene sugerencia, el juego continúa.
            log = new MemoryLog();
            move = await Selector(new FixedAdvisor(null), log).ChooseAsync(StartFen, Legal);
            Check(Legal.Contains(move) && log.Decisions[0].Outcome == "respaldo:sin-sugerencia",
                  "sin sugerencia: respaldo");

            // 4. Si la API cae, el juego continúa.
            log = new MemoryLog();
            move = await Selector(new ThrowingAdvisor(), log).ChooseAsync(StartFen, Legal);
            Check(Legal.Contains(move) && log.Decisions[0].Outcome == "respaldo:error-de-red",
                  "API caída: respaldo");

            // 5. Si la API tarda demasiado, el juego continúa.
            log = new MemoryLog();
            move = await Selector(new SlowAdvisor(), log).ChooseAsync(StartFen, Legal);
            Check(Legal.Contains(move) && log.Decisions[0].Outcome == "respaldo:timeout",
                  "timeout: respaldo");

            // 6. Se registra cada decisión (auditoría).
            Check(log.Decisions.Count == 1, "cada decisión queda registrada");

            // 7. El parseo de la respuesta tolera ruido y rechaza basura.
            Check(LlmChessAdvisor.ExtractMove("{\"content\":[{\"type\":\"text\",\"text\":\"e2e4\"}]}")?.Text == "e2e4",
                  "respuesta limpia");
            Check(LlmChessAdvisor.ExtractMove("{\"content\":[{\"type\":\"text\",\"text\":\"Mi jugada: g1f3.\"}]}")?.Text == "g1f3",
                  "respuesta con texto alrededor");
            Check(LlmChessAdvisor.ExtractMove("{\"content\":[{\"type\":\"text\",\"text\":\"no sé\"}]}") is null,
                  "respuesta sin jugada");
            Check(LlmChessAdvisor.ExtractMove("esto no es json") is null, "respuesta que no es JSON");
        }
    }

#if BONUS_DEMO
    // ========================================================================
    // DEMO: dotnet run, con la constante BONUS_DEMO definida.
    // En el TPO real, las jugadas legales las produce el generador de jugadas
    // del núcleo; acá se escriben a mano solo para mostrar el flujo.
    // ========================================================================
    public static class Demo
    {
        public static async Task Main()
        {
            await AdvisorChecks.RunAllAsync();
            Console.WriteLine();

            using var http = new HttpClient();   // en producción: IHttpClientFactory
            var fallback = new RandomChessAdvisor();
            var advisor = AdvisorFactory.CreateFromEnvironment(http, fallback);
            var selector = new AdvisedMoveSelector(
                advisor, fallback, new ConsoleAdvisorLog(), TimeSpan.FromSeconds(10));

            const string fen = "rnbqkbnr/pppppppp/8/8/8/8/PPPPPPPP/RNBQKBNR w KQkq - 0 1";
            var legal = new[] { new UciMove("e2e4"), new UciMove("d2d4"), new UciMove("g1f3"), new UciMove("b1c3") };

            // [GOBERNANZA] Transparencia: se avisa cuándo juega la IA.
            Console.WriteLine("Turno de la IA...");
            var move = await selector.ChooseAsync(fen, legal);
            Console.WriteLine($"La IA juega: {move}");
        }
    }
#endif
}
